package main
import (
    "fmt"
    "sync"
)
func main() {
    var wg sync.WaitGroup
    wg.Add(1)
    go func() {
        defer wg.Done()
        fmt.Println("Async worker finished")
    }()
    wg.Wait()
}

slides.codeSnippet:
ch := make(chan int)
go func() {
    ch <- 42 // Blocks until main receives
}()
val := <-ch // Handshake completes
fmt.Println(val)

slides.badCode:
func main() {
    ch := make(chan int)
    ch <- 1 // Fatal error: all goroutines are asleep - deadlock!
    fmt.Println(<-ch)
}

slides.goodCode:
func main() {
    ch := make(chan int, 1) // Buffered capacity of 1 avoids block
    ch <- 1
    fmt.Println(<-ch)
}

